using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using System.Windows.Forms;
namespace Astera {
sealed partial class LibraryForm {
    internal static int AuditFtlProgress(string root){try{if(Directory.Exists(root))throw new IOException("Use a new progress audit directory");Directory.CreateDirectory(root);var checks=new List<string>();int reports=0;bool flushed=false;string output=Path.Combine(root,"tool.log");Multiverse.Run(Application.ExecutablePath,new[]{"--ftl-tool-probe"},output,CancellationToken.None,s=>{},delegate(string phase,long done,long total){reports++;if(File.Exists(output))using(var reader=new StreamReader(new FileStream(output,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)))if(reader.ReadToEnd().Contains("probe started"))flushed=true;});AuditAssert(reports>0&&flushed&&File.ReadAllText(output).Contains("probe complete"),"Tool heartbeat or live-flushed output missing");checks.Add("A real child tool reports heartbeat stages and its output log is readable before completion");using(var stop=new CancellationTokenSource()){stop.CancelAfter(200);bool cancelled=false;try{Multiverse.Run(Application.ExecutablePath,new[]{"--ftl-tool-probe"},Path.Combine(root,"cancelled.log"),stop.Token,s=>{});}catch(OperationCanceledException){cancelled=true;}AuditAssert(cancelled,"Preparation did not stop its child process after cancellation");}checks.Add("Cancelling preparation stops the actual child tool without starting a game installation");
        Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var state=new Store(Path.Combine(root,"state"));state.Settings.CheckOnStart=false;state.Settings.UseMinecraftSkin=false;state.Settings.FtlDirectory=Path.Combine(root,"unavailable-ftl");using(var form=new LibraryForm(state,new Channel(),true)){form.TopMost=true;form.GameKind=2;form.SelectLibraryTab(3);form.Show();form.busy=true;form.cancellation=new CancellationTokenSource();form.workStartedUtc=DateTime.UtcNow.AddSeconds(-75);form.SetWorkProgress("Preparing Hyperspace",0,0);form.RefreshView();Application.DoEvents();AuditAssert(form.workCancel.Visible&&form.workLabel.Text.Contains("elapsed")&&form.workMeter.Fraction<0,"Settings page lacks an active indeterminate stage and global Cancel");AuditAssert(!form.releaseLabel.Visible&&form.workMeter.AnimationRunning,"Working state retained an idle status or did not start animation");int beforePaints=form.workMeter.AnimatedPaints;var measured=System.Diagnostics.Stopwatch.StartNew();MotionAudit.Pump(1200);double paintRate=(form.workMeter.AnimatedPaints-beforePaints)/measured.Elapsed.TotalSeconds;AuditAssert(paintRate>=40,"Working indicator still animates at status polling speed: "+paintRate);File.WriteAllText(Path.Combine(root,"animation-performance.json"),MC2Pack.Engine.Json.Serialize(new{MeasuredTrackPaintFps=paintRate,TrackOnly=true,StatusIntervalMs=form.workHeartbeat.Interval}));UiEffects.Enabled=false;AuditAssert(!form.workMeter.AnimationRunning,"Reduced motion kept work animation running");UiEffects.Enabled=true;form.Hide();AuditAssert(!form.workMeter.AnimationRunning,"Hidden working indicator kept animating");form.Show();AuditAssert(form.workMeter.AnimationRunning,"Restored working indicator failed to animate");checks.Add("Working track animates independently above40 paints/sec and pauses for reduced motion or hidden windows");form.Refresh();MotionAudit.Pump(250);form.CaptureVisibleUi(root,"ftl-preparation-progress");form.workCancel.PerformClick();AuditAssert(form.cancellation.IsCancellationRequested,"Global Cancel did not signal preparation");form.transaction=true;form.SetWorkProgress("Backing up and installing Multiverse",0,0);AuditAssert(!form.workCancel.Visible,"Live commit exposes unsafe cancellation");checks.Add("Settings tab exposes preparation progress and safe Cancel, while live commit hides cancellation");form.SetWorkProgress("Downloading Assets",50*1048576L,100*1048576L);AuditAssert(form.workMeter.Fraction==0.5&&form.workLabel.Text.Contains("50%")&&form.workLabel.Text.Contains("MiB"),"Download progress is not based on actual byte counts");AuditAssert(!form.workMeter.AnimationRunning,"Determinate progress kept its indeterminate animation timer");checks.Add("Known-size work displays actual percentage and MiB rather than a static full bar, with no idle animation timer");form.busy=false;form.transaction=false;form.cancellation.Dispose();form.cancellation=null;form.Close();}
        File.WriteAllText(Path.Combine(root,"result.json"),MC2Pack.Engine.Json.Serialize(new{Passed=true,Checks=checks,LiveGamesChanged=false,RealFtlExecuted=false}));return 0;
    }catch(Exception error){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());return 1;}}
}
}
